function names(ids:string[]|undefined){return (ids??[]).map(id=>catalogs.find(row=>row.id===id)?.name??'已保留的关联').join('、')||'未设置';}
function priorityText(quadrant:number|null){return quadrant===0?'紧急 · 重要':quadrant===1?'重要':quadrant===2?'紧急':'';}
