  for(const id of ['content-editor','context-editor','more-actions','comment-panel','checkpoint-panel','history-panel','materials-panel','relations-panel','analysis'])$<HTMLDetailsElement>(id).open=false;
  paintDetail();if(stored['comment:'+id]?.text||stored['comment:'+id]?.pending.length)$<HTMLDetailsElement>('comment-panel').open=true;
