  const select=node('input');select.type='checkbox';select.className='task-select';select.checked=selected.has(item.id);select.setAttribute('aria-label','选择归组：'+(item.text.split('\n')[0]||'附件事项'));select.onchange=()=>{if(select.checked)selected.set(item.id,item);else selected.delete(item.id);batchFeedback();};
  const check=node('button',item.state==='done'?'✓':'','task-check'+(item.state==='done'?' done':''));check.setAttribute('aria-label',(item.state==='done'?'恢复：':'完成：')+(item.text||'附件事项'));
  check.onclick=()=>void action(async()=>{const updated=await api.setState(item.id,item.state==='done'?'ready':'done',item.updatedAt);if(item.state!=='done'){undo={id:item.id,state:item.state,version:updated.updatedAt};$('undo-complete').hidden=false;}await refresh();status(item.state==='done'?'已恢复到待推进':'已完成，记录与资料保留');});
  const body=node('button',undefined,'task-body');body.append(node('span',item.text.split('\n')[0]||item.attachments[0]?.name||'附件事项','task-title'));
  const snippet=item.resumeNote||item.nextStep;
  if(snippet)body.append(node('span',snippet,'task-next'));
