  body.append(node('div',[priorityText(item.quadrant),(item.groupIds?.length??0)?'#'+names(item.groupIds):'',(item.personIds?.length??0)?'相关人 '+names(item.personIds):'',item.deadline?'截止 '+localTime(item.deadline).replace('T',' '):'',item.reminder?'提醒 '+localTime(item.reminder).replace('T',' '):'',item.recurrence?recurrenceText(item.recurrence):'',item.state==='waiting'&&item.waitingFor?item.waitingFor:'',materialCount?`${materialCount} 份资料`:'',item.completedAt?'完成于 '+localTime(item.completedAt).replace('T',' '):''].filter(Boolean).join(' · '),'task-meta'));

