function renderFilterOptions(){const root=$('filter-results');root.replaceChildren();filterRows.forEach((row,index)=>{const button=node('button',row.name,index===filterSelected?'active':'');button.setAttribute('role','option');button.setAttribute('aria-selected',String(index===filterSelected));button.onmousedown=event=>event.preventDefault();button.onclick=()=>chooseFilter(index);root.append(button);});if(!filterRows.length)root.append(node('p','没有匹配的分组或相关人','muted'));$('filter-options').hidden=false;$('filter-picker-query').hidden=filterSource==='query';}
function updateFilterOptions(){if(composing)return;const input=$<HTMLInputElement>('workbench-query');if(filterSource==='query'){const mention=mentionAt(input.value,input.selectionStart??input.value.length);if(!mention||mention.kind==='resource'){closeFilters();return;}filterMention=mention;}if(!filterMention)return;const query=filterSource==='query'?filterMention.query:$<HTMLInputElement>('filter-picker-query').value;const key=filterMention.kind==='group'?'groupIds':'personIds';filterRows=catalogs.filter(row=>row.kind===filterMention!.kind&&!filters[key].includes(row.id)&&catalogMatches(row,query)).slice(0,12);filterSelected=0;renderFilterOptions();}
function chooseFilter(index:number){const row=filterRows[index];if(!row||!filterMention)return;const key=row.kind==='group'?'groupIds':'personIds';filters[key]=[...new Set([...filters[key],row.id])];const query=$<HTMLInputElement>('workbench-query');if(filterSource==='query'){query.value=removeMention(query.value,filterMention);query.focus();query.setSelectionRange(filterMention.start,filterMention.start);}closeFilters();selected.clear();batchFeedback();paintFilters();void loadQueryRows().catch(error=>status(String(error),true));}
