async function loadCatalogs(){const previous=JSON.stringify(catalogs);catalogs=await api.catalog(undefined,'',true);const control=$<HTMLSelectElement>('batch-group'),value=control.value,signature=JSON.stringify(catalogs.filter(row=>row.kind==='group'&&!row.archived).map(row=>[row.id,row.name]));if(control.dataset.catalog!==signature){control.dataset.catalog=signature;control.replaceChildren(new Option('选择分组',''));for(const row of catalogs.filter(row=>row.kind==='group'&&!row.archived))control.add(new Option(row.name,row.id));control.value=value;}paintFilters();if(previous!==JSON.stringify(catalogs)){if(editing){await relationEditor.refresh();renderLinkedResources();}if(view==='catalog')await catalogManager?.refresh();if(view==='links')await linksManager?.refresh();}}
