async function refresh(){if(refreshing)return;refreshing=true;try{[all,ordered]=await Promise.all([api.items(),api.todos()]);if(editing&&!$<HTMLDialogElement>('property-dialog').open){const latest=all.find(item=>item.id===editing!.item.id);if(latest&&latest.updatedAt!==editing.item.updatedAt)receive(latest);}await loadCatalogs();await loadQueryRows();$('open-count').textContent=String(all.filter(item=>item.state!=='done').length||'');$('done-count').textContent=String(all.filter(item=>item.state==='done').length||'');renderList();locks();await loadHistories();await renderReminders();if(view==='settings')await loadProtection();}finally{refreshing=false;}}
