$('quit-app').onclick=()=>{if(busy||composing){status('正在输入或保存，请完成后再退出',true);return;}void api.quit().catch(error=>status(String(error),true));};
$('update-choose').onclick=()=>void protectionAction(async()=>{const preview=await api.chooseUpdate();updateToken=preview?.token??'';$('update-preview').hidden=!preview;if(preview)$('update-summary').textContent=`升级到 Recall ${preview.version} · 已校验 ${preview.files} 个程序文件；确认前会保全当前记录与草稿。`;});
$('update-apply').onclick=()=>void protectionAction(async()=>{if(!updateToken){status('请先选择并核对升级包',true);return;}const applied=await api.applyUpdate(updateToken);status(applied?'程序升级已安排，正在退出并重新打开…':'已取消升级，当前程序与数据保留');});
let reminderSignature='';
async function renderReminders(){const result=await api.reminders();const signature=JSON.stringify(result);if(signature===reminderSignature)return;reminderSignature=signature;$('reminders-panel').hidden=!result.items.length&&!result.error;$('reminders-title').textContent=`未处理提醒 · ${result.items.length}`;$('reminders-error').textContent=result.error;const root=$('reminders-list');root.replaceChildren();for(const row of result.items){const line=node('article',undefined,'reminder-row');const open=node('button',(row.kind==='deadline'?'截止 · ':'回访 · ')+(row.text.split('\n')[0]||'附件事项'));open.onclick=()=>void openItem(row.itemId).catch(error=>status(String(error),true));line.append(open,node('small',new Date(row.scheduledAt).toLocaleString()));for(const [label,minutes] of [['10 分钟后',10],['明天此时',1440],['已处理',null]] as const){const button=node('button',label);button.onclick=()=>void action(async()=>{await api.handleReminder(row.id,minutes);reminderSignature='';await renderReminders();status(minutes===null?'本次提醒已处理，事项状态未变':'已延后本次提醒，原截止时间不变');});line.append(button);}root.append(line);}}
api.onFlush(async()=>{if(composing||(busy&&!protectionBusy))throw new Error('正在编辑或处理事项，请稍后备份或恢复');await catalogManager?.flush();await linksManager?.flush();if($<HTMLDialogElement>('property-dialog').open)throw new Error('属性仍在编辑，请先保存或取消');if(editing)sync();await Promise.all([...draftWrites]);for(const key of draftErrors.keys()){if(key.startsWith('checkpoint:'))continue;if(stored[key])persist(key,stored[key]);else draftErrors.delete(key);}await Promise.all([...draftWrites]);if(draftErrors.size)throw new Error([...draftErrors.values()][0]);});
document.addEventListener('compositionstart',()=>{composing=true;});document.addEventListener('compositionend',()=>{composing=false;});
async function loadOpenCode(){await loadSettings();const settings={executable:openCodePath.value,model:openCodeModel.value};const info=await api.openCodeInfo();openCodeModel.replaceChildren(new Option('OpenCode 新会话默认模型',''));for(const model of info.models)openCodeModel.add(new Option(model,model));if(settings.model&&!info.models.includes(settings.model))openCodeModel.add(new Option(settings.model,settings.model));openCodeModel.value=settings.model;connectionStatus(info.version+' · 已读取可用模型');}
async function connectionAction(work:()=>Promise<void>){connectionStatus('正在处理…');await action(async()=>{try{await work();}catch(error){connectionStatus(String(error));}});}
const saveConnectionSettings=()=>api.saveOpenCodeSettings({executable:openCodePath.value,model:openCodeModel.value});
$('opencode-refresh').onclick=()=>void connectionAction(loadOpenCode);$('opencode-choose').onclick=()=>void connectionAction(async()=>{const path=await api.chooseOpenCode();if(path)openCodePath.value=path;connectionStatus('保存设置后读取模型和检查连接');});
$('opencode-save').onclick=()=>void connectionAction(async()=>{await saveConnectionSettings();connectionStatus('设置已保存。模型由 OpenCode 提供，未保存密钥。');});
$('opencode-check').onclick=()=>void connectionAction(async()=>{await saveConnectionSettings();const result=await api.checkOpenCode();connectionStatus(result.ok?result.reply+' · '+(result.model||'OpenCode 新会话默认模型'):result.message);});
$('today').textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
const boot=api.drafts().then(async values=>{stored=values;await refresh();navigate('all');});
api.onEdit(id=>void boot.then(()=>openItem(id)).catch(error=>status(String(error),true)));api.onHome(()=>void boot.then(()=>{if(busy)deferredOpen=()=>navigate('all');else navigate('all');}).catch(error=>status(String(error),true)));
async function showLink(id:string|null){if(busy){deferredOpen=()=>void showLink(id).catch(error=>status(String(error),true));return;}if($<HTMLDialogElement>('property-dialog').open)throw new Error('请先保存或取消属性编辑');const revision=++openRevision;await catalogManager?.flush();await linksManager?.flush();if(revision!==openRevision)return;navigateNow('links');if(id){await linksManager!.refresh();if(revision===openRevision&&view==='links')linksManager!.editEntry(id);}}
api.onLibrary(id=>void boot.then(()=>showLink(id)).catch(error=>status(String(error),true)));
void boot.catch(error=>status('读取失败，原数据未覆盖：'+String(error),true));
setInterval(()=>{if(!busy&&document.visibilityState==='visible')void refresh().catch(error=>status(String(error),true));},2000);
